async function main() {
  console.log(`\n📋 Total records in portal data: ${portalData.length}`);
  console.log('─'.repeat(60));

  // Collect all consumer numbers from portal data
  const consumerNumbers = [...new Set(portalData.map(r => r.consumerNumber.trim()))];
  console.log(`🔍 Unique consumer numbers to process: ${consumerNumbers.length}`);

  // Fetch matching customers from DB in batches
  console.log('\n⏳ Fetching matching customers from DB...');
  const BATCH = 50;
  const allMatches = [];

  for (let i = 0; i < consumerNumbers.length; i += BATCH) {
    const batch = consumerNumbers.slice(i, i + BATCH);
    const { data, error } = await supabase
      .from('customers')
      .select('id, customer_name, consumer_number, installation_status, subsidy_status')
      .in('consumer_number', batch);

    if (error) {
      console.error('❌ DB fetch error:', error.message);
      process.exit(1);
    }
    allMatches.push(...(data || []));
  }

  console.log(`✅ Found ${allMatches.length} matching customers in CRM`);

  // Build a lookup: consumer_number → db customer
  const dbMap = {};
  for (const c of allMatches) {
    dbMap[c.consumer_number] = c;
  }

  // Group updates
  const updates = [];
  const notFound = [];
  const skipped = [];

  for (const row of portalData) {
    const cn = row.consumerNumber.trim();
    const dbCustomer = dbMap[cn];

    if (!dbCustomer) {
      notFound.push({ cn, name: row.consumerName, status: row.statusName });
      continue;
    }

    const mapping = STATUS_MAP[row.statusName];
    if (!mapping) {
      skipped.push({ cn, name: row.consumerName, status: row.statusName });
      continue;
    }

    updates.push({
      id: dbCustomer.id,
      consumer_number: cn,
      customer_name: dbCustomer.customer_name,
      portal_status: row.statusName,
      new_subsidy_status: mapping.subsidy_status,
      new_overall_status: mapping.overall_status,
      label: mapping.label,
    });
  }

  // ── Summary before updating ──────────────────────────────────
  console.log('\n📊 Update Plan:');
  console.log(`  ✅ Will update:  ${updates.length} customers`);
  console.log(`  ❌ Not in CRM:   ${notFound.length} customers`);
  console.log(`  ⚠️  Unknown status: ${skipped.length} customers`);

  const byLabel = {};
  for (const u of updates) {
    byLabel[u.label] = (byLabel[u.label] || 0) + 1;
  }
  console.log('\n  Breakdown:');
  for (const [label, count] of Object.entries(byLabel)) {
    console.log(`    ${label}: ${count}`);
  }

  if (notFound.length > 0) {
    console.log('\n  Not found in CRM (consumer numbers):');
    notFound.forEach(n => console.log(`    - ${n.cn}  (${n.name}) [${n.status}]`));
  }

  if (updates.length === 0) {
    console.log('\n⚠️  Nothing to update. Exiting.');
    process.exit(0);
  }

  // ── Perform updates ──────────────────────────────────────────
  console.log('\n⏳ Applying updates...');
  let successCount = 0;
  let failCount = 0;

  for (const u of updates) {
    const { error } = await supabase
      .from('customers')
      .update({
        installation_status: 'completed',
        subsidy_status: u.new_subsidy_status,
        overall_status: u.new_overall_status,
      })
      .eq('id', u.id);

    if (error) {
      console.error(`  ❌ Failed: ${u.customer_name} (${u.consumer_number}) — ${error.message}`);
      failCount++;
    } else {
      console.log(`  ✅ Updated: ${u.customer_name.padEnd(40)} → install=completed | subsidy=${u.new_subsidy_status}`);
      successCount++;
    }
  }

  // ── Final summary ────────────────────────────────────────────
  console.log('\n' + '═'.repeat(60));
  console.log('🎉 DONE!');
  console.log(`  ✅ Updated successfully: ${successCount}`);
  console.log(`  ❌ Failed:               ${failCount}`);
  console.log(`  🔍 Not found in CRM:     ${notFound.length}`);
  console.log('═'.repeat(60) + '\n');
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});
